import * as T from './vendor/three.module.js';
export const fabricKinds=['cotton','linen','knit','denim','silk','velvet','leather','metallic'];
const hex=v=>typeof v==='string'&&/^#[a-fA-F0-9]{6}$/.test(v);
const num=(v,a,b)=>Number.isFinite(v)&&v>=a&&v<=b;
export function validateSurface(v){
 if(v.fabric!==undefined&&!fabricKinds.includes(v.fabric))throw Error('布料类型不正确');
 if(v.artwork!==undefined&&v.artwork!==null){const a=v.artwork;if(!a||!['repeat','front'].includes(a.layout)||!Array.isArray(a.layers)||!a.layers.length||a.layers.length>48||Object.keys(a).some(k=>!['layout','layers'].includes(k)))throw Error('图案不完整');
 for(const l of a.layers){if(!l||!['ellipse','rect','path','line','text'].includes(l.type)||Object.keys(l).some(k=>!['type','x','y','w','h','fill','stroke','lineWidth','rotation','points','text','size','smooth'].includes(k))||!(hex(l.fill)||l.fill==='none')||l.smooth!==undefined&&typeof l.smooth!=='boolean'||l.stroke!==undefined&&!hex(l.stroke)||l.lineWidth!==undefined&&!num(l.lineWidth,.001,.1)||l.rotation!==undefined&&!num(l.rotation,-Math.PI,Math.PI))throw Error('图案元素不正确');
 if(['path','line'].includes(l.type)){if(!Array.isArray(l.points)||l.points.length<(l.type==='line'?2:3)||l.points.length>48||l.points.some(p=>!Array.isArray(p)||p.length!==2||p.some(n=>!num(n,0,1))))throw Error('图案轮廓不正确');}
 else {if(!num(l.x,0,1)||!num(l.y,0,1))throw Error('图案位置不正确');if(l.type==='text'){if(typeof l.text!=='string'||!l.text.trim()||l.text.length>24||!num(l.size,.03,.4))throw Error('图案文字不正确');}else if(!num(l.w,.001,1)||!num(l.h,.001,1))throw Error('图案尺寸不正确');}
 } }
 return v;
}
export const surfaceFields={fabric:{type:'string',enum:fabricKinds},artwork:{anyOf:[{type:'null'},{type:'object',additionalProperties:false,properties:{layout:{type:'string',enum:['repeat','front']},layers:{type:'array',minItems:1,maxItems:48,items:{type:'object',additionalProperties:false,properties:{type:{type:'string',enum:['ellipse','rect','path','line','text']},x:{type:'number',minimum:0,maximum:1},y:{type:'number',minimum:0,maximum:1},w:{type:'number',minimum:.001,maximum:1},h:{type:'number',minimum:.001,maximum:1},fill:{type:'string',pattern:'^(#[a-fA-F0-9]{6}|none)$'},stroke:{type:'string',pattern:'^#[a-fA-F0-9]{6}$'},lineWidth:{type:'number',minimum:.001,maximum:.1},rotation:{type:'number',minimum:-Math.PI,maximum:Math.PI},smooth:{type:'boolean'},points:{type:'array',minItems:2,maxItems:48,items:{type:'array',minItems:2,maxItems:2,items:{type:'number',minimum:0,maximum:1}}},text:{type:'string',maxLength:24},size:{type:'number',minimum:.03,maximum:.4}},required:['type','fill']}}},required:['layout','layers']}]}};
export function drawArtwork(ctx,a,size){ctx.save();ctx.scale(size,size);for(const l of a.layers){ctx.save();ctx.fillStyle=l.fill;ctx.strokeStyle=l.stroke||l.fill;ctx.lineWidth=l.lineWidth||.008;ctx.translate(l.x||0,l.y||0);ctx.rotate(l.rotation||0);ctx.beginPath();if(l.type==='ellipse')ctx.ellipse(0,0,l.w/2,l.h/2,0,0,Math.PI*2);else if(l.type==='rect')ctx.rect(-l.w/2,-l.h/2,l.w,l.h);else if(['path','line'].includes(l.type)){ctx.moveTo(...l.points[0]);if(l.smooth){for(let i=1;i<l.points.length;i++){const p=l.points[i],n=l.points[i+1]||p;ctx.quadraticCurveTo(...p,(p[0]+n[0])/2,(p[1]+n[1])/2);}}else for(const p of l.points.slice(1))ctx.lineTo(...p);if(l.type==='path')ctx.closePath();}else{ctx.font=`600 ${l.size}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(l.text,0,0);ctx.restore();continue;}if(l.type!=='line'&&l.fill!=='none')ctx.fill();if(l.stroke||l.type==='line'){ctx.lineCap=ctx.lineJoin='round';ctx.stroke();}ctx.restore();}ctx.restore();}
export function applyGarmentSurface(material,v,{headwear=false}={}){
 const presets={cotton:[.95,.5,0],linen:[1,.25,0],knit:[1,.8,0],denim:[.9,.15,0],silk:[.3,1,0],velvet:[.85,1,0],leather:[.4,.05,0],metallic:[.3,.1,.75]},[roughness,sheen,metalness]=presets[v.fabric||'cotton'];Object.assign(material,{roughness,sheen,metalness});material.sheenColor=new T.Color(v.accent);
 if(v.artwork){const c=document.createElement('canvas');c.width=c.height=1024;const ctx=c.getContext('2d');ctx.fillStyle=v.color;ctx.fillRect(0,0,1024,1024);if(v.artwork.layout==='repeat')drawArtwork(ctx,v.artwork,1024);else{const motif=document.createElement('canvas');motif.width=motif.height=512;drawArtwork(motif.getContext('2d'),v.artwork,512);const pixels=motif.getContext('2d').getImageData(0,0,512,512).data;let x0=512,y0=512,x1=0,y1=0;for(let y=0;y<512;y++)for(let x=0;x<512;x++)if(pixels[(y*512+x)*4+3]){x0=Math.min(x0,x);y0=Math.min(y0,y);x1=Math.max(x1,x);y1=Math.max(y1,y);}const cropped=document.createElement('canvas');cropped.width=cropped.height=512;if(x0<=x1){const w=x1-x0+1,h=y1-y0+1,scale=448/Math.max(w,h);cropped.getContext('2d').drawImage(motif,x0,y0,w,h,(512-w*scale)/2,(512-h*scale)/2,w*scale,h*scale);}if(headwear)ctx.drawImage(cropped,128,384,256,512);else{const garmentHeight=v.kind==='skirt'?v.length:['top','set'].includes(v.kind)?.255+v.length*.3:.255+v.length,h=Math.min(850,.28/garmentHeight*1024),w=144,y=(1024-h)/2;ctx.drawImage(cropped,-w/2,y,w,h);ctx.drawImage(cropped,1024-w/2,y,w,h);}}
 const map=new T.CanvasTexture(c);map.flipY=false;map.colorSpace=T.SRGBColorSpace;map.wrapS=map.wrapT=T.RepeatWrapping;if(v.artwork.layout==='repeat'){const repeat=.18/v.patternScale;map.repeat.set(repeat*2,repeat);}material.map?.dispose();material.map=map;material.color.set('#ffffff');}
 if(v.fabric&&['linen','knit','denim','leather'].includes(v.fabric)){const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d');ctx.fillStyle='#888888';ctx.fillRect(0,0,128,128);ctx.strokeStyle='#bbbbbb';ctx.lineWidth=2;for(let i=-128;i<256;i+=v.fabric==='knit'?12:6){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i+(v.fabric==='denim'?128:0),128);ctx.stroke();}const map=new T.CanvasTexture(c);map.wrapS=map.wrapT=T.RepeatWrapping;map.repeat.set(12,12);material.bumpMap=map;material.bumpScale=v.fabric==='knit'?.012:.004;}
 material.needsUpdate=true;return material;
}
